#pragma once

#include <vector>
#include <functional>
#include <sstream>

#include "Shader.h"
#include "Grid.h"

// Store the information required to represent and render a mathematical function.
struct GraphData
{
	// Callable object used to evaluate the function at a given X coordinate.
	std::function<float(float)> function;

	// Vertex data generated by sampling the mathematical function.
	std::vector<Vertex> vertices;

	// Number of vertices associated with the graph.
	int vertexCount = 0;
};

class Graph 
{
public:
	// Initialize the OpenGL buffers used for graph rendering.
	Graph();

	// Release the GPU resources allocated by the graph.
	~Graph();

	// Sample a mathematical function over a specified interval and generate its vertices.
	void setFunction(std::function<float(float)> func,float startX,float endX,int segments = 500);
	
	// Render all stored functions using the provided shader and framebuffer dimensions.
	void draw(Shader& shader, int width, int height) const;
	
	// Retrieve the calculated intersections between the stored graphs and the X-axis.
	std::string getIntersectionsWithX() const;

	// Remove previously stored graphs and reset the intersection results.
	void clearVertices() { m_graphs.clear(); m_intersectionsStream.str(""); m_intersectionsStream.clear(); }

	// Prevent copying to avoid multiple objects managing the same OpenGL resources.
	Graph(const Graph&) = delete;
	Graph& operator=(const Graph&) = delete;

private:
	// Store the OpenGL objects responsible for graph vertex storage and configuration.
	GLuint VAO, VBO;

	// Keep track of the number of vertices used for rendering.
	int vertexCount;

	// Allow multiple mathematical functions to be stored and rendered independently.
	std::vector<GraphData> m_graphs;

	// Accumulate the coordinates of detected intersections with the X-axis.
	std::stringstream m_intersectionsStream{};
};